replaceOnce(
  'internal/server/server.go',
  'threads agent participant helper',
  [
    'func (s *Server) deliveryRecipients(ctx context.Context, participants []store.Participant, senderID uuid.UUID) ([]uuid.UUID, []uuid.UUID, error) {',
  ].join('\n'),
  [
    'func (s *Server) agentInstanceSenderID(ctx context.Context, identityID, senderID uuid.UUID) (bool, error) {',
    '	if !strings.EqualFold(incomingMetadataValue(ctx, identityTypeMetadataKey), agentInstanceIdentityType) {',
    '		return false, nil',
    '	}',
    '	if s.agents == nil {',
    '		return false, status.Error(codes.Internal, "agents service not configured")',
    '	}',
    '	response, err := s.agents.GetInstance(ctx, &agentsv1.GetInstanceRequest{Id: identityID.String()})',
    '	if err != nil {',
    '		return false, status.Errorf(codes.Internal, "get agent instance: %v", err)',
    '	}',
    '	instance := response.GetInstance()',
    '	if instance == nil {',
    '		return false, status.Error(codes.Internal, "get agent instance: instance missing")',
    '	}',
    '	agentID, err := parseUUID(instance.GetAgentId())',
    '	if err != nil {',
    '		return false, status.Errorf(codes.Internal, "get agent instance agent_id: %v", err)',
    '	}',
    '	return agentID == senderID, nil',
    '}',
    '',
    'func agentIdentityMaySendAsParticipant(ctx context.Context, thread store.Thread, senderID uuid.UUID) bool {',
    '\tif !isAgentIdentity(ctx) {',
    '\t\treturn false',
    '\t}',
    '\tfor _, participant := range thread.Participants {',
    '\t\tif participant.ID == senderID {',
    '\t\t\treturn true',
    '\t\t}',
    '\t}',
    '\treturn false',
    '}',
    '',
    'func (s *Server) deliveryRecipients(ctx context.Context, participants []store.Participant, senderID uuid.UUID) ([]uuid.UUID, []uuid.UUID, error) {',
  ].join('\n'),
);

